solution.exercise.c:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
void accumulate_values(const void*in,size_t n,size_t is,size_t os,value_transform fn,void*out){for(size_t i=0;i<n;i++)fn((const unsigned char*)in+i*is,(unsigned char*)out+i*os);}void accumulate(const int*in,size_t n,transform fn,int*out){for(size_t i=0;i<n;i++)out[i]=fn(in[i]);}

